window.ACTIVIDAD = {"id": "ut2-10-auditor-wcag", "titulo": "Auditor WCAG", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Revisas webs y apps como auditor o auditora de accesibilidad. Para cada problema, decide qué principio de las WCAG 2.0 incumple (perceptible, operable, comprensible o robusto) y con qué pauta se arregla.", "minutos": 25, "preguntasPorIntento": 12, "aprobado": 50, "garantizar": ["arrastrar", "emparejar"], "instrucciones": {"clasificar": "Elige el principio de las WCAG que incumple este problema.", "arrastrar": "Arrastra cada pauta al problema que resuelve. También puedes pulsar una pauta y después su zona. Sobra una pauta. Cada zona bien rellenada suma.", "emparejar": "Arrastra cada pauta junto al problema que resuelve. También puedes pulsar una pauta y después su hueco. Sobra una pauta. Cada pareja bien hecha suma."}, "diapositivas": {"152": "Persona Spectrum (Microsoft Inclusive Design): limitaciones permanentes, temporales y situacionales. Tacto: un brazo, brazo lesionado, padre o madre con un bebé en brazos. Vista: ceguera, cataratas, conductor distraído. Oído: sordera, infección de oído, camarero en un entorno ruidoso. Habla: no verbal, laringitis, acento marcado.", "155": "Limitaciones por tecnología o ambiente: contexto de uso (iluminación, visibilidad…), dispositivo de acceso (hardware o software) y conexión (alta o baja velocidad, interrupciones).", "157": "WIN-WIN: un producto accesible para personas con discapacidad facilita también el acceso a usuarios en contextos desfavorables y con otras limitaciones. Una sola acción aumenta doblemente el número de usuarios beneficiados.", "159": "Tecnologías asistenciales para discapacidad visual. Entrada: teclados (virtual, alternativo, Braille), reconocimiento de voz, apuntadores (licornios), webcams que siguen los ojos o la cara. Salida: lectores de pantalla, ampliadores de pantalla y navegadores para ciegos.", "162": "WAI, Iniciativa para la Accesibilidad Web: dentro del W3C, desarrolla estrategias, directrices y recursos para hacer la Web accesible a las personas con discapacidad.", "163": "WCAG 2.0, principio Perceptible: los componentes deben poder percibirse por algún sentido. Pautas: 1 texto descriptivo para imágenes, mapas, enlaces, botones; 2 alternativas para multimedia (subtítulos, lengua de signos); 3 contenido que pueda presentarse de diferentes maneras sin perder información ni estructura; 4 facilitar aumento de letra y de contraste; 5 en audiovisual, evitar voz en off + música.", "164": "WCAG 2.0, principio Operable: la interfaz no puede exigir una interacción imposible para el usuario. Pautas: 1 toda la funcionalidad desde el teclado; 2 tiempo suficiente para leer y usar el contenido; 3 evitar contenido que pueda causar convulsiones; 4 ayudas para navegar, localizar contenido y saber dónde se está; 5 elementos interactivos grandes y con espacio suficiente.", "165": "WCAG 2.0, principio Comprensible: la interfaz, su funcionamiento y la información deben poder comprenderse. Pautas: 1 contenido legible y comprensible, con lenguaje claro y sencillo y enlaces con nombres significativos; 2 apariencia y operatividad predecibles, repitiendo patrones; 3 ayudar a evitar y corregir errores.", "166": "WCAG 2.0, principio Robusto: el avance de las tecnologías no debe impedir que el contenido siga siendo accesible. Pauta: maximizar la compatibilidad con los agentes de usuario actuales y futuros, incluidas las tecnologías asistidas.", "167": "Niveles de accesibilidad: se agrupan por bloques de puntos cumplidos y cada bloque suma una letra A. 100 % accesible = WAI AAA o Triple A. Se puede medir con herramientas en línea como TAW."}, "banco": [{"id": "q01", "tipo": "clasificar", "enunciado": "En la tienda online Raíz, la cesta y el buscador son botones con solo un icono. Joaquín es ciego y usa un lector de pantalla. Al pasar por ellos, solo oye «botón, botón».", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Botones con icono y sin texto descriptivo", "categoria": "p"}], "explicacion": "Es perceptible. Joaquín no puede percibir qué hace cada botón, porque no tienen texto descriptivo (pauta 1: texto descriptivo para imágenes, enlaces, botones…). No es robusto: el lector de pantalla funciona bien; lo que falta es el texto que tendría que leer.", "diapositiva": 163}, {"id": "q02", "tipo": "clasificar", "enunciado": "Lidia es sorda. Quiere ver la clase de prueba de la escuela de idiomas Babel.", "imagen": "img/caso-video.svg", "alt": "Página de la escuela Babel con un vídeo: una persona hablando. Los controles son reproducir, barra de avance, volumen y pantalla completa. No hay botón de subtítulos.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Vídeo con voz y sin subtítulos", "categoria": "p"}], "explicacion": "Es perceptible. Lidia no puede percibir lo que se dice: falta una alternativa para multimedia, como subtítulos o lengua de signos (pauta 2). No es operable: el vídeo se puede poner en marcha sin problema.", "diapositiva": 163}, {"id": "q03", "tipo": "clasificar", "enunciado": "Esta es la ficha de visita del Museo de la Sal. Varias personas mayores se quejan de que no la leen bien.", "imagen": "img/caso-contraste.svg", "alt": "Página del Museo de la Sal. Un título, cuatro líneas de horario y un botón «Reservar visita». Todo el texto es gris muy claro sobre fondo blanco, y el botón es casi blanco con texto blanco.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Texto gris muy claro sobre blanco", "categoria": "p"}], "explicacion": "Es perceptible. Con tan poco contraste, el texto casi no se ve (pauta 4: facilitar el aumento de letra y de contraste). No es comprensible: el horario está bien escrito; el problema es que no se percibe.", "diapositiva": 163}, {"id": "q04", "tipo": "clasificar", "enunciado": "En el vídeo promocional de la residencia Los Olivos, una voz en off explica los servicios mientras suena música alta de fondo. Manuel tiene hipoacusia y no distingue la voz.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Voz en off mezclada con música", "categoria": "p"}], "explicacion": "Es perceptible. El temario lo dice tal cual: en contenido audiovisual evitaremos voz en off + música (pauta 5), porque la música tapa la voz. No es comprensible: el texto de la voz puede ser claro, pero no se oye.", "diapositiva": 163}, {"id": "q05", "tipo": "clasificar", "enunciado": "Elena usa la letra grande en su móvil. Al abrir la web del polideportivo, la tabla de horarios se descoloca: las columnas se mezclan y no sabe qué hora es de qué día.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "La tabla pierde su estructura al cambiar el tamaño", "categoria": "p"}], "explicacion": "Es perceptible. El contenido debe poder presentarse de diferentes maneras sin perder información ni estructura (pauta 3). Aquí, al cambiar la presentación, se pierde la relación entre horas y días. No es operable: Elena puede moverse por la página; lo que no puede es percibir bien la tabla.", "diapositiva": 163}, {"id": "q06", "tipo": "clasificar", "enunciado": "Andrés no puede usar el ratón y navega solo con el teclado. En la web de la academia Delta, el menú de cursos solo se abre al pasar el ratón por encima.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Menú que no se abre con el teclado", "categoria": "o"}], "explicacion": "Es operable. Toda la funcionalidad tiene que estar disponible desde el teclado (pauta 1). Andrés ve el menú perfectamente, así que no es perceptible: lo que no puede es usarlo.", "diapositiva": 164}, {"id": "q07", "tipo": "clasificar", "enunciado": "En la portada del hotel Brisa, las noticias pasan solas cada 2 segundos y no se pueden parar. Nuria lee despacio y nunca llega al final de ninguna.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Noticias que cambian solas sin poder pararlas", "categoria": "o"}], "explicacion": "Es operable. Hay que dar tiempo suficiente para leer y usar el contenido (pauta 2). No es comprensible: las noticias se entenderían si diera tiempo a leerlas.", "diapositiva": 164}, {"id": "q08", "tipo": "clasificar", "enunciado": "Carmen tiene temblor en las manos. Esta es la app del autobús Ruta Sur.", "imagen": "img/caso-botones.svg", "alt": "Móvil con la app Ruta Sur. Arriba, una fila de diez iconos muy pequeños y pegados entre sí. Un círculo rojo marca la yema de un dedo, que tapa varios iconos a la vez. Debajo, los próximos autobuses y un mapa.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Iconos diminutos y sin espacio entre ellos", "categoria": "o"}], "explicacion": "Es operable. Los elementos de interacción deben ser lo bastante grandes y tener espacio para que las personas con discapacidad motriz puedan usarlos (pauta 5). No es perceptible: Carmen ve los iconos, pero no consigue pulsar el que quiere.", "diapositiva": 164}, {"id": "q09", "tipo": "clasificar", "enunciado": "En la web del ayuntamiento de Valdeolmo, todas las páginas se llaman igual y el menú no marca la sección en la que estás. Marta se pierde y no sabe dónde está.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "No hay forma de saber en qué página estás", "categoria": "o"}], "explicacion": "Es operable. Una pauta de este principio pide medios que ayuden a navegar, localizar contenido y determinar dónde se encuentra el usuario (pauta 4). No es comprensible: el texto de cada página puede ser claro; lo que falla es la orientación al navegar.", "diapositiva": 164}, {"id": "q10", "tipo": "clasificar", "enunciado": "El banner de rebajas de la tienda Voltio cambia de rojo a blanco muchas veces por segundo. A Hugo, que tiene epilepsia, le puede provocar una crisis.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Destellos rápidos de color", "categoria": "o"}], "explicacion": "Es operable. El temario incluye en este principio evitar el contenido que pueda causar convulsiones (pauta 3). No es perceptible: el banner se ve de sobra; el problema es que es peligroso.", "diapositiva": 164}, {"id": "q11", "tipo": "clasificar", "enunciado": "Las instrucciones de matrícula de la escuela de música Do Re dicen: «Cumplimente el impreso habilitado al efecto conforme a la normativa vigente». Samuel no entiende qué tiene que hacer.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Instrucciones con lenguaje enrevesado", "categoria": "c"}], "explicacion": "Es comprensible. El contenido debe ser legible y comprensible, con lenguaje claro y sencillo, sobre todo para personas con discapacidad cognitiva (pauta 1). No es perceptible: Samuel lee el texto sin problema, pero no lo entiende.", "diapositiva": 165}, {"id": "q12", "tipo": "clasificar", "enunciado": "En la app del gimnasio Pulso, el botón del menú está arriba a la izquierda en unas pantallas, abajo en otras, y cada vez con un icono distinto.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "El menú cambia de sitio y de icono", "categoria": "c"}], "explicacion": "Es comprensible. La apariencia y la operatividad deben ser predecibles: hay que repetir patrones de comportamiento (pauta 2). No es operable: el botón se puede pulsar; lo difícil es entender dónde estará cada vez.", "diapositiva": 165}, {"id": "q13", "tipo": "clasificar", "enunciado": "Rosa se inscribe en la carrera Villa Verde. Al pulsar «Enviar» pasa esto.", "imagen": "img/caso-error.svg", "alt": "Formulario de inscripción con los campos Nombre, Fecha de nacimiento y DNI. Arriba, un recuadro rojo dice solo «Error 0x3F», sin indicar qué campo falla. Una nota explica que los campos ya escritos se han borrado al enviar.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Mensaje de error que no dice qué falla ni cómo arreglarlo", "categoria": "c"}], "explicacion": "Es comprensible. Hay que ayudar a los usuarios a evitar los errores y a corregirlos (pauta 3). «Error 0x3F» no explica nada, y borrar lo escrito obliga a empezar de cero. No es robusto: el formulario funciona; lo que falla es la ayuda a la persona.", "diapositiva": 165}, {"id": "q14", "tipo": "clasificar", "enunciado": "La web de la autoescuela Ceda el Paso solo funciona bien en un navegador concreto. En los demás, los botones no responden.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "Solo funciona en un navegador", "categoria": "r"}], "explicacion": "Es robusto. Hay que maximizar la compatibilidad con los agentes de usuario actuales y futuros (navegadores, lectores de pantalla…). No es operable: en el navegador correcto todo se maneja bien; el fallo depende de la tecnología.", "diapositiva": 166}, {"id": "q15", "tipo": "clasificar", "enunciado": "Tras una actualización, el lector de pantalla de Joaquín ya no reconoce las casillas del formulario de la biblioteca Letras: la web las dibuja como imágenes que el lector no sabe interpretar.", "categorias": [{"id": "p", "texto": "Perceptible"}, {"id": "o", "texto": "Operable"}, {"id": "c", "texto": "Comprensible"}, {"id": "r", "texto": "Robusto"}], "elementos": [{"id": "e1", "texto": "La web no es compatible con el lector de pantalla", "categoria": "r"}], "explicacion": "Es robusto. La pauta pide maximizar la compatibilidad con los agentes de usuario, incluidas las tecnologías asistidas. Si la web está hecha de forma que el lector no puede interpretarla, deja de ser accesible aunque se vea bien.", "diapositiva": 166}, {"id": "q16", "tipo": "unica", "enunciado": "En la web de la piscina municipal, el horario es solo una foto de un cartel. El lector de pantalla de Joaquín dice «imagen» y nada más. ¿Qué pauta incumple?", "opciones": [{"id": "a", "texto": "Perceptible: texto descriptivo para imágenes, mapas, enlaces y botones.", "correcta": true}, {"id": "b", "texto": "Robusto: compatibilidad con agentes de usuario y tecnologías asistidas."}, {"id": "c", "texto": "Operable: toda la funcionalidad disponible desde el teclado."}, {"id": "d", "texto": "Comprensible: apariencia y operatividad predecibles."}], "explicacion": "Falta el texto descriptivo de la imagen, así que el horario no se puede percibir (Perceptible, pauta 1). La opción de robusto engaña: el lector de pantalla funciona; no lee nada porque nadie ha escrito ese texto.", "diapositiva": 163}, {"id": "q17", "tipo": "unica", "enunciado": "Para elegir butaca en el cine Mirador hay que arrastrar con el ratón. Andrés navega solo con el teclado y no puede comprar. ¿Qué pauta incumple?", "opciones": [{"id": "a", "texto": "Operable: toda la funcionalidad disponible desde el teclado.", "correcta": true}, {"id": "b", "texto": "Operable: elementos grandes y con espacio entre ellos."}, {"id": "c", "texto": "Perceptible: contenido presentable de distintas maneras."}, {"id": "d", "texto": "Comprensible: ayudar a evitar y a corregir errores."}], "explicacion": "Toda la funcionalidad debe estar disponible desde el teclado (Operable, pauta 1). El tamaño de las butacas da igual si no se pueden elegir con el teclado. No es perceptible: Andrés ve la sala perfectamente.", "diapositiva": 164}, {"id": "q18", "tipo": "unica", "enunciado": "La web de la autoescuela Ruedas da 30 segundos para escribir el código que llega por SMS. Encarna lee despacio y siempre se le acaba el tiempo. Todas las opciones son del principio Operable. ¿Qué pauta incumple?", "opciones": [{"id": "a", "texto": "Tiempo suficiente para leer y usar el contenido.", "correcta": true}, {"id": "b", "texto": "Toda la funcionalidad disponible desde el teclado."}, {"id": "c", "texto": "Ayudas para navegar y saber dónde se encuentra."}, {"id": "d", "texto": "Elementos grandes y con espacio entre ellos."}], "explicacion": "Hay que dar tiempo suficiente para leer y usar el contenido (pauta 2). Encarna puede escribir el código con el teclado y sabe dónde está; lo que le falta es tiempo.", "diapositiva": 164}, {"id": "q19", "tipo": "arrastrar", "grupo": "auditoria", "enunciado": "Auditas la portada del Teatro La Lonja. Hay un problema en cada zona. ¿Qué pauta lo resuelve?", "imagen": "img/auditoria-teatro.svg", "alt": "Portada del Teatro La Lonja. Zona 1: una foto del escenario; el lector de pantalla dice «imagen, IMG_0234.jpg». Zona 2: un párrafo sobre la temporada en letra pequeña y gris muy claro sobre blanco. Zona 3: un banner «¡Oferta!» que cambia de rojo a amarillo 6 veces por segundo. Zona 4: el apartado «Cómo comprar», que dice «La adquisición de localidades se efectuará mediante el procedimiento telemático habilitado al efecto…».", "zonas": [{"id": "z1", "x": 25, "y": 30, "correcta": "t1"}, {"id": "z2", "x": 72, "y": 30, "correcta": "t2"}, {"id": "z3", "x": 28, "y": 70, "correcta": "t3"}, {"id": "z4", "x": 72, "y": 72, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Texto descriptivo"}, {"id": "t2", "texto": "Letra y contraste"}, {"id": "t3", "texto": "Evitar convulsiones"}, {"id": "t4", "texto": "Lenguaje claro"}, {"id": "t5", "texto": "Uso con teclado"}], "explicacion": "Zona 1: la foto no tiene texto descriptivo (Perceptible, pauta 1). Zona 2: el gris claro y la letra pequeña piden facilitar el aumento de letra y de contraste (Perceptible, pauta 4). Zona 3: los destellos rápidos pueden causar convulsiones (Operable, pauta 3). Zona 4: el texto necesita lenguaje claro y sencillo (Comprensible, pauta 1). Sobra el teclado: en una imagen fija no se puede comprobar.", "diapositiva": 163}, {"id": "q20", "tipo": "arrastrar", "grupo": "auditoria", "enunciado": "Auditas la tienda online Hilo Rojo. Hay un problema en cada zona. ¿Qué pauta lo resuelve?", "imagen": "img/auditoria-tienda.svg", "alt": "Tienda Hilo Rojo. Zona 1: en el móvil, una fila de doce iconos diminutos y pegados; la yema de un dedo tapa varios a la vez. Zona 2: un vídeo tutorial en el que la profesora explica hablando; los controles son reproducir, volumen y pantalla completa. Zona 3: el campo Código postal en rojo con el mensaje «Dato no válido», sin decir qué falla. Zona 4: el aviso «Tu cesta caduca en 0:15; si llega a cero se vacía y no se puede ampliar».", "zonas": [{"id": "z1", "x": 30, "y": 13, "correcta": "t1"}, {"id": "z2", "x": 25, "y": 45, "correcta": "t2"}, {"id": "z3", "x": 72, "y": 59, "correcta": "t3"}, {"id": "z4", "x": 72, "y": 22, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Tamaño y espacio"}, {"id": "t2", "texto": "Alternativas multimedia"}, {"id": "t3", "texto": "Ayuda con los errores"}, {"id": "t4", "texto": "Tiempo suficiente"}, {"id": "t5", "texto": "Compatibilidad"}], "explicacion": "Zona 1: los iconos necesitan tamaño y espacio para poder pulsarlos (Operable, pauta 5). Zona 2: el vídeo necesita subtítulos o lengua de signos (Perceptible, pauta 2). Zona 3: el mensaje debe ayudar a corregir el error, por ejemplo «escribe cinco números» (Comprensible, pauta 3). Zona 4: la cuenta atrás no da tiempo suficiente (Operable, pauta 2). Sobra la compatibilidad: no hay ningún fallo de navegador ni de lector de pantalla.", "diapositiva": 164}, {"id": "q21", "tipo": "emparejar", "grupo": "parejas", "enunciado": "Estos problemas aparecen en la web de una agencia de viajes. Empareja cada uno con la pauta que lo resuelve.", "pares": [{"id": "p1", "izquierda": "El mapa de destinos es una imagen sin texto que la describa.", "derecha": "Texto descriptivo para imágenes y mapas"}, {"id": "p2", "izquierda": "El vídeo del crucero no tiene subtítulos.", "derecha": "Alternativas para multimedia"}, {"id": "p3", "izquierda": "El buscador de vuelos no se puede usar sin ratón.", "derecha": "Toda la funcionalidad desde el teclado"}, {"id": "p4", "izquierda": "Si la fecha está mal, el formulario se borra sin explicar nada.", "derecha": "Ayudar a evitar y corregir errores"}], "distractores": ["Evitar voz en off con música"], "explicacion": "Mapa sin texto: texto descriptivo (Perceptible 1). Vídeo sin subtítulos: alternativas para multimedia (Perceptible 2). Buscador sin teclado: toda la funcionalidad desde el teclado (Operable 1). Formulario que se borra: ayudar a evitar y corregir errores (Comprensible 3). Sobra «voz en off con música»: ningún problema habla de audio mezclado.", "diapositiva": 165}, {"id": "q22", "tipo": "emparejar", "grupo": "parejas", "enunciado": "Estos problemas aparecen en la app de un banco. Empareja cada uno con la pauta que lo resuelve.", "pares": [{"id": "p1", "izquierda": "La sesión se cierra a los 20 segundos de leer un contrato.", "derecha": "Tiempo suficiente para leer y usar"}, {"id": "p2", "izquierda": "El botón «Transferir» mide como la uña de un dedo meñique.", "derecha": "Elementos grandes y con espacio"}, {"id": "p3", "izquierda": "Cada pantalla coloca el botón «Atrás» en un sitio distinto.", "derecha": "Apariencia y operatividad predecibles"}, {"id": "p4", "izquierda": "La app deja de funcionar con el lector de pantalla del móvil.", "derecha": "Compatibilidad con tecnologías asistidas"}], "distractores": ["Contenido sin destellos que causen convulsiones"], "explicacion": "Sesión de 20 segundos: tiempo suficiente (Operable 2). Botón diminuto: elementos grandes y con espacio (Operable 5). «Atrás» que cambia de sitio: apariencia y operatividad predecibles (Comprensible 2). Fallo con el lector: compatibilidad con agentes de usuario y tecnologías asistidas (Robusto). Sobran los destellos: ningún problema habla de luces que parpadean.", "diapositiva": 164}, {"id": "q23", "tipo": "clasificar", "enunciado": "El Persona Spectrum de Microsoft clasifica las limitaciones según cuánto duran. ¿De qué tipo es cada una?", "instruccion": "Elige un tipo de limitación para cada persona. Cada persona bien clasificada suma.", "categorias": [{"id": "pe", "texto": "Permanente"}, {"id": "te", "texto": "Temporal"}, {"id": "si", "texto": "Situacional"}], "elementos": [{"id": "e1", "texto": "Pilar es sorda de nacimiento.", "categoria": "pe"}, {"id": "e2", "texto": "Ernesto perdió un brazo hace años.", "categoria": "pe"}, {"id": "e3", "texto": "Sofía lleva el brazo escayolado tres semanas.", "categoria": "te"}, {"id": "e4", "texto": "Rocío tiene laringitis y no puede usar el asistente de voz.", "categoria": "te"}, {"id": "e5", "texto": "Iván sostiene a su bebé con un brazo mientras usa el móvil.", "categoria": "si"}, {"id": "e6", "texto": "Un camarero no oye el aviso del móvil por el ruido del bar.", "categoria": "si"}], "explicacion": "Permanente: dura siempre (sordera, un solo brazo). Temporal: se cura (brazo lesionado, laringitis). Situacional: depende del momento (un bebé en brazos, un entorno ruidoso). Son los mismos ejemplos del Persona Spectrum: una solución pensada para una persona con un brazo ayuda también a quien lleva un bebé.", "diapositiva": 152}, {"id": "q24", "tipo": "clasificar", "enunciado": "Las limitaciones de acceso no son solo discapacidades. ¿De qué tipo es cada una?", "instruccion": "Elige un tipo de limitación para cada caso. Cada caso bien clasificado suma.", "categorias": [{"id": "in", "texto": "Propia de la persona"}, {"id": "te", "texto": "Tecnológica"}, {"id": "am", "texto": "Ambiental"}], "elementos": [{"id": "e1", "texto": "Hamid acaba de llegar a España y aún no lee bien en español.", "categoria": "in"}, {"id": "e2", "texto": "Teresa nunca ha comprado en una tienda online.", "categoria": "in"}, {"id": "e3", "texto": "El móvil de Óscar es muy antiguo y tiene la pantalla diminuta.", "categoria": "te"}, {"id": "e4", "texto": "En el pueblo de Ana, la conexión a internet se corta a menudo.", "categoria": "te"}, {"id": "e5", "texto": "Luis mira el horario del bus a pleno sol y casi no ve la pantalla.", "categoria": "am"}, {"id": "e6", "texto": "Marta está en una sala de espera llena de humo y ve la pantalla borrosa.", "categoria": "am"}], "explicacion": "Propias de la persona: idioma, conocimientos y experiencia (además de las discapacidades). Tecnológicas: el dispositivo (hardware o software) y la conexión. Ambientales: el contexto de uso, como la iluminación o la visibilidad. Recuerda: las dificultades no son solo por diversidad funcional.", "diapositiva": 155}, {"id": "q25", "tipo": "clasificar", "enunciado": "Estas son tecnologías asistenciales para personas con discapacidad visual. ¿Cuáles son de entrada y cuáles de salida?", "instruccion": "Elige si cada tecnología es de entrada o de salida. Cada una bien clasificada suma.", "categorias": [{"id": "en", "texto": "Dispositivo de entrada"}, {"id": "sa", "texto": "Dispositivo de salida"}], "elementos": [{"id": "e1", "texto": "Teclado Braille", "categoria": "en"}, {"id": "e2", "texto": "Software de reconocimiento de voz", "categoria": "en"}, {"id": "e3", "texto": "Licornio (apuntador de cabeza)", "categoria": "en"}, {"id": "e4", "texto": "Webcam que sigue los ojos o la cara", "categoria": "en"}, {"id": "e5", "texto": "Lector de pantalla", "categoria": "sa"}, {"id": "e6", "texto": "Ampliador de pantalla", "categoria": "sa"}], "explicacion": "Los de entrada sirven para dar órdenes al ordenador: teclados (también Braille), reconocimiento de voz, licornios y webcams que siguen los ojos. Los de salida presentan la información a la persona: lectores y ampliadores de pantalla, y navegadores para ciegos.", "diapositiva": 159}, {"id": "q26", "tipo": "vf", "enunciado": "Hacer una web accesible solo beneficia a las personas con discapacidad.", "correcta": false, "explicacion": "Es falso. Es un WIN-WIN: lo que hace accesible una web para personas con discapacidad ayuda también a quien está en un contexto desfavorable. Por ejemplo, quien tiene visión reducida comparte problema con quien mira una pantalla pequeña o en un entorno con humo.", "diapositiva": 157}, {"id": "q27", "tipo": "vf", "enunciado": "Una web que alcanza el nivel A ya es 100 % accesible.", "correcta": false, "explicacion": "Es falso. Los niveles se agrupan por bloques de puntos cumplidos y cada bloque suma una letra A. El 100 % accesible es el nivel WAI AAA o Triple A.", "diapositiva": 167}, {"id": "q28", "tipo": "unica", "enunciado": "¿Qué es la WAI?", "opciones": [{"id": "a", "texto": "La iniciativa del W3C que crea directrices y recursos para hacer la web accesible.", "correcta": true}, {"id": "b", "texto": "Una herramienta en línea que mide el nivel de accesibilidad de un sitio web."}, {"id": "c", "texto": "Un programa de tecnología asistencial que lee en voz alta lo que hay en pantalla."}, {"id": "d", "texto": "La comisión europea que en 2002 pidió webs públicas accesibles a la ciudadanía."}], "explicacion": "La WAI (Iniciativa para la Accesibilidad Web) está dentro del W3C y desarrolla estrategias, directrices y recursos para la accesibilidad. La herramienta para medir es, por ejemplo, TAW. El programa que lee la pantalla es un lector de pantalla. La comisión es eEurope 2002.", "diapositiva": 162}, {"id": "q29", "tipo": "unica", "enunciado": "Tu cliente quiere saber qué nivel de accesibilidad tiene su web antes de rediseñarla. ¿Qué le propones según el temario?", "opciones": [{"id": "a", "texto": "Analizarla con una herramienta en línea como TAW.", "correcta": true}, {"id": "b", "texto": "Preguntar en una encuesta si a la gente le gusta la web."}, {"id": "c", "texto": "Comprobar que se ve bien en el ordenador del equipo."}, {"id": "d", "texto": "Contar cuántas imágenes y vídeos tiene cada página."}], "explicacion": "Para medir la accesibilidad se pueden usar herramientas en línea como TAW. Que la web guste o se vea bien en un ordenador no dice nada de si la pueden usar todas las personas. Contar imágenes tampoco: lo importante es si tienen texto descriptivo.", "diapositiva": 167}]};
